// Contract goal matrix: each ordinary bounty settles against actual engine race outcomes.
// Synthetic previous-place fixtures and near-deadline contracts exercise edge conditions;
// race effects, shop replacement, wear and placements are generated by the real engine.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const html=fs.readFileSync(path.join(__dirname,'..','dist/dev.html'),'utf8');
const scripts=[...html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/g)].map(m=>m[1]);
const ctx=vm.createContext({console});ctx.window=ctx;ctx.globalThis=ctx;
for(const i of [0,1,2,3,25])vm.runInContext(scripts[i],ctx);
const E=ctx.ScrapEngine,D=ctx.ScrapData,clone=o=>JSON.parse(JSON.stringify(o));
const legacyIds=new Set(['third','second','fourth','fifth','match','drop','reckless','balanced','careful','clean','survivor','worn','comeback','route','fresh']);
const regular=Array.from(E.bountyDefinitions).filter(d=>legacyIds.has(d.id));
assert.equal(regular.length,15);
function expectation(id,r,previous,pre){
 if(r.failedSlot||r.noStart)return false;
 switch(id){
 case 'third':return r.place===3;
 case 'second':return r.place===2;
 case 'fourth':return r.place===4;
 case 'fifth':return r.place===5;
 case 'match':return !!previous&&!previous.noStart&&!previous.failedSlot&&r.place===previous.place;
 case 'drop':return !!previous&&!previous.noStart&&!previous.failedSlot&&r.place-previous.place>=2;
 case 'reckless':return r.place<=2&&r.approach==='reckless';
 case 'balanced':return r.place<=3&&r.approach==='balanced';
 case 'careful':return r.place<=2&&r.approach==='careful';
 case 'clean':return r.damage<=15;
 case 'survivor':return r.damage<=24; // fixture starts with 1 successful qualifying race
 case 'worn':return Object.keys(r.durabilityBefore).some(k=>['engine','tyres','chassis'].includes(k)&&r.durabilityBefore[k]<=25);
 case 'comeback':return !!previous&&previous.place-r.place>=2;
 case 'route':return r.place<=3&&r.laps.some(l=>l.effects.some(x=>x.choiceEvent&&x.choice==='risk'&&x.outcome==='success'));
 case 'fresh':return pre.garageAction?.kind==='replace'&&r.place<=2;
 default:throw Error('Goal missing from test '+id);
 }
}
const results={};
for(const def of regular){
 let success=0,failure=0;
 for(let seed=1;seed<=450;seed++){
   let s=clone(E.newRun(seed*17+3));
   s.raceIndex=(seed*11)%40;
   const build=seed%4;
   if(build===1)s.loadout={...D.GAG_RECIPES.find(g=>g.id==='f1').requires};
   if(build===2)s.loadout={...D.GAG_RECIPES.find(g=>g.id==='tank').requires};
   if(build===3)s.loadout={engine:'clunker',tyres:'balloon-tyres',chassis:'wobble-wagon',gadget:'cooling-fan'};
   for(const slot of D.SLOTS)if(build)s.levels[slot]=Math.min(10,2+Math.floor(s.raceIndex/6));
   s.approach=['careful','balanced','reckless'][seed%3];
   s.durability={engine:100,tyres:100,chassis:def.id==='worn'&&seed%2===0?25:100,gadget:100};
   if(['comeback','match','drop'].includes(def.id)){
     const prev={place:def.id==='drop'?1+(seed%2):1+(seed%5),noStart:false,failedSlot:null};
     s.history=[prev];
   }
   if(def.id==='fresh'){
     s.credits=100000;const o=E.shopOffers(s)[0];s=clone(E.buy(s,o.id));
   }
   const previous=s.history?.at(-1)||null;
   const choices={};
   if(def.id==='route')for(const ev of E.raceCard(s.seed,s.raceIndex,s).events){
     if(E.eventDefinition(ev)?.delivery==='choice')choices[ev.key]='risk';
   }
   s.bounties=[{id:def.id,remaining:1,progress:def.id==='survivor'?1:0}];
   const out=clone(E.race(s,choices)),r=out.history.at(-1);
   const goal=expectation(def.id,r,previous,s);
   assert.equal(r.bountyResults?.[0]?.success,!!goal,'Incorrect '+def.id+' outcome for seed '+seed);
   assert.equal(out.bounties.length,0,'Expired/completed contract still occupies slot');
   assert.doesNotThrow(()=>E.decodeSave(E.encodeSave(out)),'Contract settlement corrupted save');
   if(goal)success++;else failure++;
 }
 results[def.id]={success,failure};
 assert(success>0,'No successful result found for '+def.id+' across 450 varied seeds');
 assert(failure>0,'No failure found for '+def.id+' across 450 varied seeds');
}
console.log('BOUNTY GOAL MATRIX:',JSON.stringify(results));
console.log('PASS: all 15 ordinary goals demonstrably winnable/failable; outcomes and saved states agree.');
